-- Writes modules/engine_handles.lua from the engine's library per handle under types/recoil/generated/. Those files
-- are RecoilEngine PR #2799's rts/Lua/handles output, vendored byte for byte; types/recoil/README.md has the recipe.
-- Run from the repo root after a refresh:
--   luajit tools/engine_handles/generate.lua
-- spec/modules/engine_handles_spec.lua fails until the generated file matches the types again.
package.path = "./?.lua;" .. package.path
local Derive = require("tools/engine_handles/derive")

local syncedOnly, unsyncedOnly = Derive.Sides()
local syncedGlobals, unsyncedGlobals = Derive.Globals()
assert(syncedOnly and unsyncedOnly and syncedGlobals and unsyncedGlobals, "types/recoil/generated/ is not here")

---@param names string[]
---@return string
local function block(names)
	local lines = {}
	for _, name in ipairs(names) do
		lines[#lines + 1] = string.format('\t\t"%s",', name)
	end
	return table.concat(lines, "\n")
end

local out = assert(io.open("modules/engine_handles.lua", "w"))
out:write(
	"-- GENERATED by tools/engine_handles/generate.lua from types/recoil/generated/; do not edit.\n"
		.. "-- What the engine registers in one Lua handle only: the Spring functions, which modules/module_env.lua refuses\n"
		.. "-- from a file declared for the other handle, or for any, and the globals (constants tables, enums, the gl\n"
		.. "-- surface); spec/modules/engine_handles_spec.lua fails when this drifts.\n"
		.. "---@class EngineHandles\n"
		.. "---@field syncedOnly string[]\n"
		.. "---@field unsyncedOnly string[]\n"
		.. "---@field syncedOnlyGlobals string[]\n"
		.. "---@field unsyncedOnlyGlobals string[]\n"
		.. "return {\n\tsyncedOnly = {\n"
		.. block(Derive.Sorted(syncedOnly))
		.. "\n\t},\n\tunsyncedOnly = {\n"
		.. block(Derive.Sorted(unsyncedOnly))
		.. "\n\t},\n\tsyncedOnlyGlobals = {\n"
		.. block(Derive.Sorted(syncedGlobals))
		.. "\n\t},\n\tunsyncedOnlyGlobals = {\n"
		.. block(Derive.Sorted(unsyncedGlobals))
		.. "\n\t},\n}\n"
)
out:close()
print(
	string.format(
		"modules/engine_handles.lua: %d synced-only, %d unsynced-only; globals %d synced-only, %d unsynced-only",
		#Derive.Sorted(syncedOnly),
		#Derive.Sorted(unsyncedOnly),
		#Derive.Sorted(syncedGlobals),
		#Derive.Sorted(unsyncedGlobals)
	)
)
